const raw = (($json.target) || '').trim().toLowerCase();
const authorized = $json.authorized === true || $json.authorized === 'true';
const hostnameRe = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)*$/;
const ipv4Re = /^(\d{1,3}\.){3}\d{1,3}$/;
const ipv6Re = /^[0-9a-f:]+$/i;
const isIp = ipv4Re.test(raw) || (raw.includes(':') && ipv6Re.test(raw));
const valid = raw.length > 0 && raw.length < 254 && (isIp || hostnameRe.test(raw));
const blocked = !authorized ? 'authorization checkbox not confirmed' : (!valid ? 'target failed validation' : null);
return [{ json: { target: raw, isIp, scanIntensity: $json.scanIntensity || 'dns-only', blocked } }];

const target = $('Validate & Normalize').item.json.target;
const lines = ($json.stdout || '').split('\n');
const records = { A: [], AAAA: [], MX: [], NS: [], TXT: [], SOA: [] };
let section = null;
for (const line of lines) {
  const t = line.trim();
  if (!t) continue;
  const marker = t.match(/^(A|AAAA|MX|NS|TXT|SOA):$/);
  if (marker) { section = marker[1]; continue; }
  if (section && records[section]) records[section].push(t);
}
return [{ json: { target, records } }];

const dnsInfo = $('Parse DNS').item.json;
const norm = $('Validate & Normalize').item.json;
let subdomains = [];
try {
  const body = $json.body !== undefined ? $json.body : $json;
  const arr = Array.isArray(body) ? body : [];
  const set = new Set();
  for (const entry of arr) {
    if (entry && entry.name_value) {
      entry.name_value.split('\n').forEach(n => set.add(n.trim().toLowerCase()));
    }
  }
  subdomains = Array.from(set);
} catch (e) { subdomains = []; }

let whoisText = '';
try { whoisText = $('WHOIS Lookup').item.json.stdout || ''; } catch (e) { whoisText = ''; }
const whoisFields = {};
